package br.com.inpetu.android;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import org.json.*;
import java.security.*;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

public final class Store extends SQLiteOpenHelper {
 public static final String VERSION="0.1.0-experimental.1";
 static final String[] NAMES={"Milena","Bernardo","João F","João E","Guilherme"};
 static final String[] LOGINS={"milena","bernardo","joaof","joaoe","guilherme"};
 static final String[] PASSWORDS={"milena040","bernardo040","joaof040","joaoe040","guilherme040"};
 private final String session=UUID.randomUUID().toString();
 private long user=0;
 private String userName="";
 private boolean admin=false;
 private Clock clock=Clock.systemDefaultZone();
 public Store(Context context){this(context,"inpetu-android.db");}
 Store(Context context,String name){super(context,name,null,1);getWritableDatabase();}
 void setClock(Clock value){clock=value;}
 public LocalDate today(){return LocalDate.now(clock);}
 public LocalDateTime now(){return LocalDateTime.now(clock);}
 @Override public void onConfigure(SQLiteDatabase db){db.setForeignKeyConstraintsEnabled(true);}
 @Override public void onCreate(SQLiteDatabase db){
  db.execSQL("CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,login TEXT NOT NULL UNIQUE,role TEXT NOT NULL,salt BLOB NOT NULL,hash BLOB NOT NULL)");
  db.execSQL("CREATE TABLE spaces(id INTEGER PRIMARY KEY,name TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)))");
  db.execSQL("CREATE TABLE personas(code TEXT PRIMARY KEY,name TEXT NOT NULL,quota INTEGER CHECK(quota IS NULL OR quota>=0))");
  db.execSQL("CREATE TABLE config(id INTEGER PRIMARY KEY CHECK(id=1),opening INTEGER NOT NULL,closing INTEGER NOT NULL,hours INTEGER NOT NULL CHECK(hours>0),operation INTEGER,cleaning INTEGER,supplies INTEGER)");
  db.execSQL("INSERT INTO config(id,opening,closing,hours) VALUES(1,480,1200,4)");
  db.execSQL("CREATE TABLE prices(year INTEGER NOT NULL,turns INTEGER NOT NULL,pct INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),PRIMARY KEY(year,turns,pct))");
  db.execSQL("CREATE TABLE holidays(day TEXT PRIMARY KEY,name TEXT NOT NULL)");
  db.execSQL("CREATE TABLE bookings(id INTEGER PRIMARY KEY,space INTEGER NOT NULL REFERENCES spaces(id),persona TEXT NOT NULL REFERENCES personas(code),title TEXT NOT NULL,person TEXT NOT NULL,cnpj TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,company TEXT NOT NULL,city TEXT NOT NULL,day TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,participants INTEGER NOT NULL CHECK(participants>0),created TEXT NOT NULL,expires TEXT NOT NULL,status TEXT NOT NULL,paid INTEGER NOT NULL,academic INTEGER NOT NULL,financed INTEGER NOT NULL,uses_quota INTEGER NOT NULL DEFAULT 0,quota_minutes INTEGER NOT NULL DEFAULT 0,amount INTEGER NOT NULL DEFAULT 0,deposit_pct INTEGER NOT NULL DEFAULT 30,deposit INTEGER NOT NULL DEFAULT 0,payment TEXT NOT NULL DEFAULT 'PENDENTE',reason TEXT NOT NULL DEFAULT '')");
  db.execSQL("CREATE TABLE movements(id INTEGER PRIMARY KEY,persona TEXT NOT NULL REFERENCES personas(code),month TEXT NOT NULL,minutes INTEGER NOT NULL,booking INTEGER NOT NULL REFERENCES bookings(id),kind TEXT NOT NULL)");
  db.execSQL("CREATE TABLE events(id INTEGER PRIMARY KEY,time TEXT NOT NULL,version TEXT NOT NULL,session TEXT NOT NULL,level TEXT NOT NULL,event TEXT NOT NULL,actor INTEGER NOT NULL,target INTEGER NOT NULL,error_type TEXT NOT NULL)");
  for(int i=0;i<5;i++){byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);ContentValues v=new ContentValues();v.put("id",i+1);v.put("name",NAMES[i]);v.put("login",LOGINS[i]);v.put("role",i==1?"ADMIN":"COLABORADOR");v.put("salt",salt);v.put("hash",hash(PASSWORDS[i],salt));db.insertOrThrow("users",null,v);}
  String[] personas={"InPETU Hub","UFSC outros","Ecossistema Sapiens Parque","Governo, ICTs e 3º setor","Parceiros do InPETU","Externos"};int[] quotas={-1,1800,1200,600,600,-1};
  for(int i=0;i<6;i++){ContentValues v=new ContentValues();v.put("code","P"+(i+1));v.put("name",personas[i]);if(quotas[i]>=0)v.put("quota",quotas[i]);db.insertOrThrow("personas",null,v);}
  int[] amounts={160000,280000,360000};for(int t=1;t<=3;t++)for(int pct:new int[]{100,75,50})db.execSQL("INSERT INTO prices VALUES(2026,?,?,?)",new Object[]{t,pct,Rules.percent(amounts[t-1],pct)});
  for(String d:new String[]{"2026-10-12","2026-11-02","2026-11-15","2026-11-20","2026-12-25"})db.execSQL("INSERT INTO holidays VALUES(?,?)",new Object[]{d,"Feriado de referência 2026"});
 }
 @Override public void onUpgrade(SQLiteDatabase db,int old,int current){throw new IllegalStateException("Migração Android não implementada; banco preservado.");}
 static byte[] hash(String password,byte[] salt){PBEKeySpec spec=new PBEKeySpec(password.toCharArray(),salt,60000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}catch(Exception e){throw new IllegalStateException("Falha na proteção do acesso",e);}finally{spec.clearPassword();}}
 public boolean login(String login,String password){logoutSilently();try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM users WHERE login=?",new String[]{login.trim().toLowerCase(Locale.ROOT)})){if(c.moveToFirst()&&MessageDigest.isEqual(c.getBlob(c.getColumnIndexOrThrow("hash")),hash(password,c.getBlob(c.getColumnIndexOrThrow("salt"))))){user=c.getLong(0);userName=c.getString(1);admin="ADMIN".equals(c.getString(3));event("INFO","LOGIN_OK",0,null);return true;}}event("WARN","LOGIN_DENIED",0,null);return false;}
 private void logoutSilently(){user=0;userName="";admin=false;}
 public void logout(){event("INFO","LOGOUT",0,null);logoutSilently();}
 public boolean logged(){return user>0;}public boolean admin(){return logged()&&admin;}public String name(){return userName;}
 private void auth(){Rules.require(logged(),"Entre para continuar.");}
 private void adminOnly(){auth();Rules.require(admin,"Esta ação exige o administrador Bernardo.");}
 public void event(String level,String code,long target,Throwable error){
  if(!code.matches("[A-Z_]{1,64}"))code="OTHER";if(!Arrays.asList("INFO","WARN","ERROR").contains(level))level="INFO";
  ContentValues v=new ContentValues();v.put("time",Instant.now(clock).toString());v.put("version",VERSION);v.put("session",session);v.put("level",level);v.put("event",code);v.put("actor",user);v.put("target",target);v.put("error_type",error==null?"":error.getClass().getName());
  SQLiteDatabase db=getWritableDatabase();db.insertOrThrow("events",null,v);db.execSQL("DELETE FROM events WHERE id NOT IN (SELECT id FROM events ORDER BY id DESC LIMIT 5000)");
 }
 public List<JSONObject> rows(String sql,String...args){List<JSONObject> list=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext()){JSONObject j=new JSONObject();for(int i=0;i<c.getColumnCount();i++)try{if(c.isNull(i))j.put(c.getColumnName(i),JSONObject.NULL);else if(c.getType(i)==Cursor.FIELD_TYPE_INTEGER)j.put(c.getColumnName(i),c.getLong(i));else j.put(c.getColumnName(i),c.getString(i));}catch(JSONException e){throw new IllegalStateException(e);}list.add(j);}}return list;}
 public JSONObject one(String sql,String...args){List<JSONObject> r=rows(sql,args);Rules.require(!r.isEmpty(),"Registro não encontrado.");return r.get(0);}
 public List<JSONObject> spaces(){return rows("SELECT * FROM spaces ORDER BY name,id");}
 public long saveSpace(Long id,String name,String capacity,boolean active,boolean available){auth();ContentValues v=new ContentValues();v.put("name",Rules.text(name,255,"Nome do espaço"));v.put("capacity",Rules.integer(capacity,"Capacidade"));v.put("active",active?1:0);v.put("available",available?1:0);long result=id==null?getWritableDatabase().insertOrThrow("spaces",null,v):id;if(id!=null)Rules.require(getWritableDatabase().update("spaces",v,"id=?",new String[]{id.toString()})==1,"Espaço não encontrado.");event("INFO",id==null?"SPACE_CREATED":"SPACE_UPDATED",result,null);return result;}
 public JSONObject config(){return one("SELECT * FROM config WHERE id=1");}
 public void saveConfig(int opening,int closing,int hours,long operation,long cleaning,long supplies){adminOnly();Rules.require(opening>=0&&closing<=1440&&closing>opening&&hours>0&&hours<=24,"Confira o expediente e horas por turno.");Rules.require(operation>=0&&cleaning>=0&&supplies>=0,"As taxas não podem ser negativas.");getWritableDatabase().execSQL("UPDATE config SET opening=?,closing=?,hours=?,operation=?,cleaning=?,supplies=? WHERE id=1",new Object[]{opening,closing,hours,operation,cleaning,supplies});event("INFO","CONFIG_UPDATED",1,null);}
 public void savePrice(int year,int turns,int pct,long amount){adminOnly();Rules.require(year>=2026&&year<=2100&&turns>=1&&turns<=24&&Arrays.asList(100,75,50).contains(pct)&&amount>=0,"Confira os dados da tabela de preços.");getWritableDatabase().execSQL("INSERT OR REPLACE INTO prices VALUES(?,?,?,?)",new Object[]{year,turns,pct,amount});event("INFO","PRICE_UPDATED",0,null);}
 public void saveHoliday(LocalDate day,String name){adminOnly();getWritableDatabase().execSQL("INSERT OR REPLACE INTO holidays VALUES(?,?)",new Object[]{day.toString(),Rules.text(name,255,"Feriado")});event("INFO","HOLIDAY_UPDATED",0,null);}
 public void saveQuota(String persona,int minutes){adminOnly();Rules.require(minutes>=0&&minutes<=600000,"Confira a cota.");Rules.require(getWritableDatabase().update("personas",values("quota",minutes),"code=?",new String[]{persona})==1,"Persona inválida.");event("INFO","QUOTA_UPDATED",0,null);}
 private static ContentValues values(String name,int value){ContentValues v=new ContentValues();v.put(name,value);return v;}
 public void expire(){getWritableDatabase().execSQL("UPDATE bookings SET status='EXPIRADA' WHERE status='PENDENTE' AND expires<?",new Object[]{now().toString()});}
 public List<JSONObject> bookings(LocalDate day){auth();expire();return rows("SELECT b.*,s.name AS space_name,s.capacity FROM bookings b JOIN spaces s ON s.id=b.space WHERE b.day=? ORDER BY b.start,b.id",day.toString());}
 public JSONObject booking(long id){auth();expire();return one("SELECT b.*,s.name AS space_name FROM bookings b JOIN spaces s ON s.id=b.space WHERE b.id=?",Long.toString(id));}
 private void validate(long space,LocalDate day,int start,int end,int count,long ignore){JSONObject s=one("SELECT * FROM spaces WHERE id=?",Long.toString(space)),c=config();Rules.require(s.optInt("active")==1&&s.optInt("available")==1,"Este espaço está indisponível.");Rules.schedule(day,start,end,count,s.optInt("capacity"),c.optInt("opening"),c.optInt("closing"),now());Rules.require(rows("SELECT id FROM bookings WHERE space=? AND day=? AND status='APROVADA' AND start<? AND end>? AND id<>?",Long.toString(space),day.toString(),Integer.toString(end),Integer.toString(start),Long.toString(ignore)).isEmpty(),"Horário indisponível: já existe reserva aprovada.");}
 public int[] quota(String persona,YearMonth target){JSONObject p=one("SELECT * FROM personas WHERE code=?",persona);int limit=p.optInt("quota",0),debt=0,used=0;List<JSONObject> movements=rows("SELECT month,SUM(minutes) AS total FROM movements WHERE persona=? AND month<=? GROUP BY month ORDER BY month",persona,target.toString());YearMonth first=movements.isEmpty()?target:YearMonth.parse(movements.get(0).optString("month"));for(YearMonth m=first;!m.isAfter(target);m=m.plusMonths(1)){used=debt;for(JSONObject row:movements)if(row.optString("month").equals(m.toString()))used+=row.optInt("total");used=Math.max(0,used);debt=Math.max(0,used-limit);}return new int[]{limit,used,Math.max(0,limit-used),debt};}
 private JSONObject quote(JSONObject b){try{String persona=b.getString("persona");LocalDate day=LocalDate.parse(b.getString("day"));JSONObject p=one("SELECT * FROM personas WHERE code=?",persona),c=config();int minutes=b.getInt("end")-b.getInt("start");int turns=(int)Math.ceil(minutes/(c.getInt("hours")*60.0));boolean eligible=!p.isNull("quota")&&ChronoUnit.DAYS.between(LocalDateTime.parse(b.getString("created")).toLocalDate(),day)>=15;boolean use=eligible&&quota(persona,YearMonth.from(day))[2]>=minutes;boolean paid=b.optInt("paid")==1||b.optInt("financed")==1,academic=b.optInt("academic")==1;Rules.require(!persona.equals("P2")||paid||academic,"Para P2 sem pagamento/financiamento, indique atividade acadêmica.");int[] t=Rules.taxes(persona,use,paid,academic);one("SELECT amount FROM prices WHERE year=? AND turns=? AND pct=100",Integer.toString(day.getYear()),Integer.toString(turns));long rent=t[0]==0?0:one("SELECT amount FROM prices WHERE year=? AND turns=? AND pct=?",Integer.toString(day.getYear()),Integer.toString(turns),Integer.toString(t[0])).getLong("amount");String cleaning=t[3]==1?"supplies":"cleaning";boolean fees=(t[1]==0||!c.isNull("operation"))&&(t[2]==0||!c.isNull(cleaning));long total=rent+Rules.percent(c.optLong("operation",0),t[1])+Rules.percent(c.optLong(cleaning,0),t[2]);int percent=Rules.deposit(day,!rows("SELECT day FROM holidays WHERE day=?",day.toString()).isEmpty());return new JSONObject().put("uses_quota",use?1:0).put("quota_minutes",use?minutes:0).put("amount",total).put("deposit_pct",percent).put("deposit",Rules.percent(total,percent)).put("fees",fees);}catch(JSONException e){throw new IllegalArgumentException("Confira os dados da reserva.");}}
 public long createBooking(JSONObject input){auth();SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{
  for(String key:new String[]{"title","person","cnpj","email","phone","company","city","day","persona"})input.put(key,Rules.text(input.optString(key),255,key));
  Rules.require(input.getString("cnpj").matches("[0-9]{14}"),"CNPJ deve ter 14 dígitos.");Rules.require(input.getString("email").matches("[^\\s@]+@[^\\s@.]+(?:\\.[^\\s@.]+)+"),"Confira o email.");Rules.require(input.getString("phone").matches("[+0-9 ()-]{8,30}")&&input.getString("phone").replaceAll("[^0-9]","").length()>=8,"Confira o telefone.");
  validate(input.getLong("space"),LocalDate.parse(input.getString("day")),input.getInt("start"),input.getInt("end"),input.getInt("participants"),-1);
  input.put("created",now().toString());input.put("expires",now().plusHours(24).toString());JSONObject quote=quote(input);ContentValues v=new ContentValues();v.put("space",input.getLong("space"));for(String key:new String[]{"start","end","participants","paid","academic","financed"})v.put(key,input.optInt(key));for(String key:new String[]{"title","person","cnpj","email","phone","company","city","day","persona","created","expires"})v.put(key,input.getString(key));v.put("status","PENDENTE");for(String key:new String[]{"uses_quota","quota_minutes","amount","deposit_pct","deposit"})v.put(key,quote.getLong(key));long id=db.insertOrThrow("bookings",null,v);event("INFO","BOOKING_CREATED",id,null);db.setTransactionSuccessful();return id;
 }catch(JSONException e){throw new IllegalArgumentException("Confira os dados da reserva.");}finally{db.endTransaction();}}
 private void move(JSONObject b,int minutes,String month,String kind){getWritableDatabase().execSQL("INSERT INTO movements(persona,month,minutes,booking,kind) VALUES(?,?,?,?,?)",new Object[]{b.optString("persona"),month,minutes,b.optLong("id"),kind});}
 public void approve(long id,boolean identity){auth();SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject b=booking(id);Rules.require(identity,"Confirme a conferência do vínculo com a instituição.");Rules.require(b.optString("status").equals("PENDENTE"),"Somente reserva pendente pode ser aprovada.");validate(b.optLong("space"),LocalDate.parse(b.optString("day")),b.optInt("start"),b.optInt("end"),b.optInt("participants"),id);JSONObject q=quote(b);Rules.require(q.optBoolean("fees"),"O administrador deve configurar as taxas (zero quando não há cobrança).");ContentValues v=new ContentValues();v.put("status","APROVADA");for(String key:new String[]{"uses_quota","quota_minutes","amount","deposit_pct","deposit"})v.put(key,q.optLong(key));db.update("bookings",v,"id=?",new String[]{Long.toString(id)});if(q.optInt("uses_quota")==1)move(b,q.optInt("quota_minutes"),b.optString("day").substring(0,7),"UTILIZACAO");event("INFO","BOOKING_APPROVED",id,null);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public void reject(long id,String reason){auth();JSONObject b=booking(id);Rules.require(b.optString("status").equals("PENDENTE"),"Somente pendente pode ser recusada.");reason=Rules.text(reason,2000,"Motivo");getWritableDatabase().execSQL("UPDATE bookings SET status='RECUSADA',reason=? WHERE id=?",new Object[]{reason,id});event("INFO","BOOKING_REJECTED",id,null);}
 public void cancel(long id,String reason,boolean force){auth();SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject b=booking(id);String state=b.optString("status");Rules.require(state.equals("PENDENTE")||state.equals("APROVADA"),"Esta reserva não permite cancelamento.");reason=Rules.text(reason,2000,"Justificativa");Rules.require(!force||admin,"Força maior exige o administrador.");if(state.equals("APROVADA")&&b.optInt("uses_quota")==1){move(b,-b.optInt("quota_minutes"),b.optString("day").substring(0,7),"ESTORNO");if(!force&&ChronoUnit.DAYS.between(today(),LocalDate.parse(b.optString("day")))<30)move(b,b.optInt("quota_minutes")*2,YearMonth.from(today()).toString(),"PENALIDADE");}db.execSQL("UPDATE bookings SET status='CANCELADA',reason=? WHERE id=?",new Object[]{reason,id});event("INFO","BOOKING_CANCELLED",id,null);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public void payment(long id,String state){auth();JSONObject b=booking(id);Rules.require(Arrays.asList("APROVADA","CONCLUIDA").contains(b.optString("status")),"Registre pagamento após aprovação.");Rules.require(Arrays.asList("PENDENTE","SINAL_PAGO","PAGO").contains(state),"Situação de pagamento inválida.");getWritableDatabase().execSQL("UPDATE bookings SET payment=? WHERE id=?",new Object[]{state,id});event("INFO","PAYMENT_RECORDED",id,null);}
 public void complete(long id){auth();JSONObject b=booking(id);Rules.require(b.optString("status").equals("APROVADA")&&!LocalDate.parse(b.optString("day")).atTime(b.optInt("end")/60,b.optInt("end")%60).isAfter(now()),"Só é possível concluir após o fim de uma reserva aprovada.");getWritableDatabase().execSQL("UPDATE bookings SET status='CONCLUIDA' WHERE id=?",new Object[]{id});event("INFO","BOOKING_COMPLETED",id,null);}
 public String logExport(){auth();StringBuilder text=new StringBuilder("InPETU Android EXPERIMENTAL "+VERSION+"\nEventos locais; sem envio automático. Últimos 5000 eventos.\n");for(JSONObject e:rows("SELECT * FROM events ORDER BY id"))text.append(e.toString()).append('\n');return text.toString();}
 public String backup(){adminOnly();try{JSONObject root=new JSONObject().put("schema",1).put("platform","android-offline").put("version",VERSION);for(String table:TABLES)root.put(table,new JSONArray(rows("SELECT * FROM "+table)));event("INFO","BACKUP_EXPORTED",0,null);return root.toString();}catch(JSONException e){throw new IllegalStateException(e);}}
 private static final String[] TABLES={"spaces","personas","config","prices","holidays","bookings","movements"};
 public void restore(String data){adminOnly();Rules.require(data.length()<8*1024*1024,"Backup excede 8 MiB.");Rules.require(rows("SELECT id FROM spaces LIMIT 1").isEmpty()&&rows("SELECT id FROM bookings LIMIT 1").isEmpty(),"Restaure somente numa instalação vazia; seus dados atuais foram preservados.");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject root=new JSONObject(data);Rules.require(root.optInt("schema")==1&&root.optString("platform").equals("android-offline"),"Formato de backup incompatível.");Set<String> keys=new HashSet<>(Arrays.asList(TABLES));keys.addAll(Arrays.asList("schema","platform","version"));Iterator<String> it=root.keys();while(it.hasNext())Rules.require(keys.contains(it.next()),"Campo desconhecido no backup.");for(String t:new String[]{"movements","bookings","spaces","personas","config","prices","holidays"})db.delete(t,null,null);for(String table:TABLES){JSONArray array=root.getJSONArray(table);Rules.require(array.length()<=20000,"Backup muito grande.");Set<String> columns=new HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info("+table+")",null)){while(c.moveToNext())columns.add(c.getString(1));}for(int i=0;i<array.length();i++){JSONObject row=array.getJSONObject(i);ContentValues values=new ContentValues();Iterator<String> names=row.keys();while(names.hasNext()){String key=names.next();Rules.require(columns.contains(key),"Coluna desconhecida no backup.");Object value=row.get(key);if(value==JSONObject.NULL)values.putNull(key);else if(value instanceof Number)values.put(key,((Number)value).longValue());else if(value instanceof String)values.put(key,(String)value);else throw new IllegalArgumentException("Tipo inválido no backup.");}db.insertOrThrow(table,null,values);}}Rules.require(rows("SELECT id FROM config WHERE id=1").size()==1&&rows("SELECT code FROM personas").size()==6,"Configuração incompleta.");event("INFO","BACKUP_RESTORED",0,null);db.setTransactionSuccessful();}catch(JSONException e){throw new IllegalArgumentException("Backup inválido.");}finally{db.endTransaction();}}
}
